1	"use server";
2	
3	import { z } from "zod";
4	
5	const DemoRequestSchema = z.object({
6	  name: z.string().min(2, "Name required"),
7	  email: z.string().email("Valid email required"),
8	  studioName: z.string().min(2, "Studio name required"),
9	  chairs: z.enum(['1', '2-5', '6-10', '11+']),
10	  currentTool: z.string().min(1, "Tell us what you're using now"),
11	  preferredTime: z.enum(['weekday-am', 'weekday-pm', 'weekend', 'flexible']),
12	  notes: z.string().max(500).optional(),
13	});
14	
15	export interface DemoFormState {
16	  status: 'idle' | 'success' | 'error';
17	  message?: string;
18	  errors?: Record<string, string>;
19	}
20	
21	export async function submitDemoRequest(
22	  prevState: DemoFormState,
23	  formData: FormData
24	): Promise<DemoFormState> {
25	  const raw = {
26	    name: formData.get('name')?.toString() ?? '',
27	    email: formData.get('email')?.toString() ?? '',
28	    studioName: formData.get('studioName')?.toString() ?? '',
29	    chairs: formData.get('chairs')?.toString() ?? '',
30	    currentTool: formData.get('currentTool')?.toString() ?? '',
31	    preferredTime: formData.get('preferredTime')?.toString() ?? '',
32	    notes: formData.get('notes')?.toString() ?? '',
33	  };
34	
35	  const parsed = DemoRequestSchema.safeParse(raw);
36	  if (!parsed.success) {
37	    const errors: Record<string, string> = {};
38	    for (const issue of parsed.error.issues) {
39	      const path = issue.path[0]?.toString();
40	      if (path && !errors[path]) errors[path] = issue.message;
41	    }
42	    return { status: 'error', message: 'Please fix the errors below', errors };
43	  }
44	
45	  // TODO: send to Resend / Boldteq inbox. For v1, log to console + simulate success.
46	  // eslint-disable-next-line no-console
47	  console.log('[DEMO REQUEST]', parsed.data);
48	
49	  await new Promise<void>(r => setTimeout(r, 600));
50	
51	  return {
52	    status: 'success',
53	    message: "We'll be in touch within one business day at the email you gave us.",
54	  };
55	}
