49	// ─── FormField ────────────────────────────────────────────────────────────────
50	interface FormFieldProps {
51	  label: string;
52	  name: string;
53	  type: "text" | "email";
54	  placeholder?: string;
55	  error?: string;
56	  required?: boolean;
57	}
58	
59	function FormField({ label, name, type, placeholder, error, required }: FormFieldProps) {
60	  const [focused, setFocused] = useState(false);
61	  return (
62	    <div style={wrapperStyle}>
63	      <label htmlFor={name} style={labelStyle}>
64	        {label}
65	        {required && (
66	          <span style={{ color: BRAND.rust, marginLeft: 2 }} aria-hidden="true">
67	            *
68	          </span>
69	        )}
70	      </label>
71	      <input
72	        id={name}
73	        name={name}
74	        type={type}
75	        placeholder={placeholder}
76	        required={required}
77	        aria-invalid={!!error}
78	        aria-describedby={error ? `${name}-error` : undefined}
79	        style={inputBase(focused)}
80	        onFocus={() => setFocused(true)}
81	        onBlur={() => setFocused(false)}
82	      />
83	      {error && (
84	        <p id={`${name}-error`} style={errorStyle} role="alert">
85	          {error}
86	        </p>
87	      )}
88	    </div>
89	  );
