138	          <option key={opt.value} value={opt.value} disabled={opt.disabled}>
139	            {opt.label}
140	          </option>
141	        ))}
142	      </select>
143	      {error && (
144	        <p id={`${name}-error`} style={errorStyle} role="alert">
145	          {error}
146	        </p>
147	      )}
148	    </div>
149	  );
150	}
151	
152	// ─── FormTextarea ─────────────────────────────────────────────────────────────
153	interface FormTextareaProps {
154	  label: string;
155	  name: string;
156	  placeholder?: string;
157	  error?: string;
158	  rows?: number;
159	}
160	
161	function FormTextarea({ label, name, placeholder, error, rows = 3 }: FormTextareaProps) {
162	  const [focused, setFocused] = useState(false);
163	  return (
164	    <div style={wrapperStyle}>
165	      <label htmlFor={name} style={labelStyle}>
166	        {label}
167	      </label>
