169	        id={name}
170	        name={name}
171	        placeholder={placeholder}
172	        rows={rows}
173	        aria-invalid={!!error}
174	        aria-describedby={error ? `${name}-error` : undefined}
175	        style={{
176	          ...inputBase(focused),
177	          resize: "vertical",
178	          minHeight: 80,
179	        }}
180	        onFocus={() => setFocused(true)}
181	        onBlur={() => setFocused(false)}
182	      />
183	      {error && (
184	        <p id={`${name}-error`} style={errorStyle} role="alert">
185	          {error}
186	        </p>
187	      )}
188	    </div>
189	  );
190	}
191	
192	// ─── Chair options ────────────────────────────────────────────────────────────
193	const CHAIR_OPTIONS: FormSelectOption[] = [
194	  { value: "", label: "Select…", disabled: true },
195	  { value: "1", label: "1 (solo)" },
196	  { value: "2-5", label: "2 – 5" },
197	  { value: "6-10", label: "6 – 10" },
198	  { value: "11+", label: "11+" },
199	];
200	
201	const TIME_OPTIONS: FormSelectOption[] = [
202	  { value: "", label: "Select…", disabled: true },
203	  { value: "weekday-am", label: "Weekday morning" },
204	  { value: "weekday-pm", label: "Weekday afternoon" },
205	  { value: "weekend", label: "Weekend" },
206	  { value: "flexible", label: "I'm flexible" },
207	];
208	
209	// ─── DemoForm ─────────────────────────────────────────────────────────────────
210	export function DemoForm() {
211	  const [state, formAction, isPending] = useActionState(submitDemoRequest, initialState);
212	
213	  const cardStyle: React.CSSProperties = {
214	    background: BRAND.white,
215	    borderRadius: 18,
216	    padding: "32px 28px",
