218	    border: `1px solid ${BRAND.borderSoft}`,
219	  };
220	
221	  // ─── Success state ────────────────────────────────────────────────────────
222	  if (state.status === "success") {
223	    return (
224	      <div style={{ ...cardStyle, textAlign: "center" }}>
225	        <div
226	          style={{
227	            width: 56,
228	            height: 56,
229	            borderRadius: "50%",
230	            background: BRAND.sageWash,
231	            display: "flex",
232	            alignItems: "center",
233	            justifyContent: "center",
234	            margin: "0 auto 20px",
235	          }}
236	          aria-hidden="true"
237	        >
238	          <Check size={24} color={BRAND.sage} strokeWidth={2.5} />
239	        </div>
240	        <h3
241	          style={{
242	            fontFamily: FONT.serif,
243	            fontSize: 28,
244	            color: BRAND.onyx,
245	            fontWeight: 400,
246	            marginBottom: 12,
247	          }}
248	        >
249	          You&rsquo;re booked.
250	        </h3>
251	        <p
252	          style={{
253	            fontFamily: FONT.sans,
254	            fontSize: 15,
255	            color: BRAND.stoneDark,
256	            lineHeight: 1.6,
257	            maxWidth: 380,
258	            margin: "0 auto",
259	          }}
260	        >
261	          {state.message}
