263	      </div>
264	    );
265	  }
266	
267	  // ─── Form state ───────────────────────────────────────────────────────────
268	  const errors = state.errors ?? {};
269	
270	  return (
271	    <div style={cardStyle}>
272	      {state.status === "error" && state.message && (
273	        <div
274	          role="alert"
275	          style={{
276	            padding: "10px 14px",
277	            background: BRAND.crimsonSoft,
278	            color: BRAND.crimson,
279	            borderRadius: 8,
280	            fontFamily: FONT.sans,
281	            fontSize: 13,
282	            marginBottom: 16,
283	          }}
284	        >
285	          {state.message}
286	        </div>
287	      )}
288	
289	      <form action={formAction} noValidate>
290	        <FormField
291	          label="Your name"
292	          name="name"
293	          type="text"
294	          placeholder="Jane Doe"
295	          error={errors.name}
296	          required
297	        />
298	        <FormField
299	          label="Email"
300	          name="email"
301	          type="email"
302	          placeholder="jane@yourstudio.com"
303	          error={errors.email}
304	          required
305	        />
306	        <FormField
307	          label="Studio name"
308	          name="studioName"
309	          type="text"
310	          placeholder="Midnight Ink Studio"
311	          error={errors.studioName}
312	          required
313	        />
314	
315	        {/* 2-col grid for chairs + time */}
316	        <div
317	          style={{
318	            display: "grid",
319	            gridTemplateColumns: "1fr 1fr",
320	            gap: 12,
321	          }}
322	        >
323	          <FormSelect
324	            label="Chairs"
325	            name="chairs"
326	            options={CHAIR_OPTIONS}
327	            error={errors.chairs}
328	            required
329	          />
330	          <FormSelect
331	            label="Preferred time"
332	            name="preferredTime"
333	            options={TIME_OPTIONS}
334	            error={errors.preferredTime}
335	            required
336	          />
337	        </div>
338	
339	        <FormField
340	          label="What are you using now?"
341	          name="currentTool"
342	          type="text"
343	          placeholder="Fresha, spreadsheets, pen & paper…"
344	          error={errors.currentTool}
345	          required
346	        />
347	        <FormTextarea
348	          label="Anything else we should know?"
349	          name="notes"
350	          placeholder="Specific pain points, questions, or special circumstances…"
351	          error={errors.notes}
352	          rows={3}
353	        />
354	
355	        <button
356	          type="submit"
357	          disabled={isPending}
358	          style={{
359	            display: "flex",
360	            alignItems: "center",
361	            justifyContent: "center",
362	            gap: 8,
363	            width: "100%",
364	            padding: "14px 20px",
365	            borderRadius: 100,
366	            background: isPending ? BRAND.coal : BRAND.onyx,
367	            color: BRAND.bone,
368	            fontFamily: FONT.sans,
369	            fontSize: 15,
370	            fontWeight: 600,
371	            border: "none",
372	            cursor: isPending ? "wait" : "pointer",
373	            opacity: isPending ? 0.7 : 1,
374	            transition: "opacity 0.15s ease, background 0.15s ease",
375	            marginTop: 8,
376	          }}
377	          aria-busy={isPending}
378	        >
379	          {isPending ? "Sending…" : "Book my walkthrough"}
380	          {!isPending && <ArrowRight size={15} strokeWidth={2} />}
381	        </button>
382	
383	        <p
384	          style={{
385	            fontFamily: FONT.sans,
386	            fontSize: 12,
387	            color: BRAND.stoneFaint,
388	            textAlign: "center",
389	            marginTop: 12,
390	            marginBottom: 0,
391	          }}
392	        >
393	          We respond within one business day. No calendar tetris.
394	        </p>
395	      </form>
396	    </div>
397	  );
398	}
