3	import React from "react";
4	import { usePathname } from "next/navigation";
5	import Link from "next/link";
6	import { ChevronRight } from "lucide-react";
7	import { BRAND, FONT } from "@/lib/brand";
8	
9	interface PageBreadcrumbsProps {
10	  labelMap?: Record<string, string>;
11	}
12	
13	function slugToTitle(slug: string): string {
14	  return slug
15	    .split("-")
16	    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
17	    .join(" ");
18	}
19	
20	interface Crumb {
21	  label: string;
22	  href: string;
23	}
24	
25	export function PageBreadcrumbs({ labelMap }: PageBreadcrumbsProps) {
26	  const pathname = usePathname();
27	  const segments = pathname.split("/").filter(Boolean);
28	
29	  if (segments.length === 0) return null;
30	
31	  const crumbs: Crumb[] = [{ label: "Home", href: "/" }];
32	  let cumulative = "";
33	  for (const segment of segments) {
34	    cumulative += `/${segment}`;
35	    crumbs.push({
36	      label: labelMap?.[segment] ?? slugToTitle(segment),
37	      href: cumulative,
38	    });
39	  }
40	
41	  return (
42	    <div
43	      style={{
44	        maxWidth: 1280,
45	        margin: "0 auto",
46	        padding: "14px 32px",
47	        display: "flex",
48	        alignItems: "center",
49	        gap: 6,
50	      } as React.CSSProperties}
51	    >
52	      {crumbs.map((crumb, i) => {
53	        const isLast = i === crumbs.length - 1;
54	        return (
55	          <React.Fragment key={crumb.href}>
56	            {i > 0 && (
57	              <ChevronRight size={12} color={BRAND.stoneLight} strokeWidth={2} />
58	            )}
59	            {isLast ? (
60	              <span
61	                style={{
62	                  fontFamily: FONT.sans,
63	                  fontSize: 12,
64	                  color: BRAND.stoneDark,
65	                } as React.CSSProperties}
66	              >
67	                {crumb.label}
68	              </span>
69	            ) : (
70	              <Link
71	                href={crumb.href}
72	                style={{
73	                  fontFamily: FONT.sans,
74	                  fontSize: 12,
75	                  color: BRAND.stone,
76	                  textDecoration: "none",
77	                } as React.CSSProperties}
78	              >
79	                {crumb.label}
80	              </Link>
81	            )}
82	          </React.Fragment>
83	        );
84	      })}
85	    </div>
86	  );
87	}
